"""A XAdES generated by Firma Perú or ReFirma, verified by berigna (PR-INT-05, BRG-CAL-006).

The signatures of real people carry their name and DNI: they stay out of this repository
(in the internal documentation) and the script takes their path. It verifies with the
bundled store plus the TSL of INDECOPI cached by berigna, online (OCSP and CRL of RENIEC),
and prints the result with the common name of the signer, the DNI masked, to compare with
the validator of Firma Perú.

    .venv/bin/python tests/interop/verificar_firma_peru.py firmado.xml [documento-separado]
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from berigna.core.report.explanations import display_name
from berigna.core.trust import TrustStore
from berigna.core.trust.cache import TslCache
from berigna.core.trust.tsl import extend_store
from berigna.core.validation.xades import verify_xades


def main() -> int:
    if len(sys.argv) not in (2, 3):
        print(__doc__)
        return 2
    store = TrustStore.load_bundled()
    trusted_list = TslCache(Path.home() / ".local/share/berigna/tsl").load()
    if trusted_list is not None:
        store = extend_store(store, trusted_list)
    content = Path(sys.argv[2]).read_bytes() if len(sys.argv) == 3 else None
    verification = verify_xades(Path(sys.argv[1]).read_bytes(), store, content=content)
    print(f"TSL de INDECOPI: {'sí' if trusted_list is not None else 'no (solo el almacén propio)'}")
    for report in verification.signatures:
        signer = display_name(report.signer.subject) if report.signer else "-"
        print(
            f"| {report.packaging.value} | {report.indication.name} | "
            f"{report.subindication or '-'} | {report.scope.value if report.scope else '-'} | "
            f"{signer} | {report.claimed_signing_time} |"
        )
    return 0


if __name__ == "__main__":
    sys.exit(main())
